import java.util.*;
import java.io.*;

public class Main {
    static long[] rootPath(long n, long x) {
        // Write your solution here
        // Return the labels from the root to x, or {-1} if x is not in the tree.
        return new long[]{-1};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        long n = (long) in.nval;
        in.nextToken();
        long x = (long) in.nval;
        long[] path = rootPath(n, x);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < path.length; i++) sb.append(path[i]).append(i + 1 < path.length ? " " : "\n");
        System.out.print(sb);
    }
}
